begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select count(*)::integer from public.playlists where kind='editorial' and creator_id is null),1,'starter exists without a fake creator');
select lives_ok('select private.ensure_curated_starter_playlist()','starter initialization is idempotent');
create temporary table playlist_session_state(name text primary key,value jsonb);
grant select,insert,update on playlist_session_state to authenticated,anon;
set local role anon;
insert into playlist_session_state values('detail',public.get_library_playlist('7ecf3523-18cb-5cbe-a307-5b5cd43d1836'));
select is(value->'credit','{"kind":"editorial","displayName":"Would You Peek"}'::jsonb,'public editorial credit') from playlist_session_state where name='detail';
select is(jsonb_array_length(value->'items'),3,'starter lists original three items') from playlist_session_state where name='detail';
select ok(not (value ?| array['creatorId','creatorEmail','question','options','videoId','assetId','setup','reveal','analysis','observedAction']),'detail exposes only playlist metadata') from playlist_session_state where name='detail';
select ok(not exists(select 1 from jsonb_array_elements(value->'items') i where i ?| array['question','options','videoId','assetId','setup','reveal','analysis','observedAction']),'item preview discloses no playback or answers') from playlist_session_state where name='detail';
select is(jsonb_array_length(public.list_library_playlists(' TENZ ')->'playlists'),1,'normalized player search finds starter');
select is(jsonb_array_length(public.list_library_playlists('missing-name')->'playlists'),0,'unmatched player query is empty');
select throws_ok($$select public.list_library_playlists('',null,'AA')$$,'P0001','INVALID_REQUEST','malformed cursor fails closed');
reset role;
insert into auth.users(id,email,email_confirmed_at) values('72000000-0000-4000-8000-000000000001','playlist-learner@example.test',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"72000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.start_playlist_training_session('72000000-0000-4000-8000-000000000010','7ecf3523-18cb-5cbe-a307-5b5cd43d1836','72000000-0000-4000-8000-000000000099')$$,'P0001','PLAYLIST_CHANGED','start requires exact seen publication');
insert into playlist_session_state values('start',public.start_playlist_training_session('72000000-0000-4000-8000-000000000010','7ecf3523-18cb-5cbe-a307-5b5cd43d1836','2e061c34-3f9c-58cd-8923-926b353662fc'));
select is(value->'session'->'target','{"kind":"playlist","playlistId":"7ecf3523-18cb-5cbe-a307-5b5cd43d1836"}'::jsonb,'session records playlist target') from playlist_session_state where name='start';
select is(value->'session'->'playlist'->'credit','{"kind":"editorial","displayName":"Would You Peek"}'::jsonb,'session freezes editorial credit') from playlist_session_state where name='start';
select is(jsonb_array_length(value->'session'->'items'),3,'session freezes full original order') from playlist_session_state where name='start';
select is(public.start_playlist_training_session('72000000-0000-4000-8000-000000000010','7ecf3523-18cb-5cbe-a307-5b5cd43d1836','2e061c34-3f9c-58cd-8923-926b353662fc')->>'replayed','true','exact session start retries original receipt');
select throws_ok($$select public.start_selected_training_session('72000000-0000-4000-8000-000000000011','{"kind":"scenario","scenarioId":"bind-clove-smoke-contest"}')$$,'P0001','ACTIVE_SESSION_EXISTS','other target cannot silently replace playlist');
reset role;
update public.scenarios set is_published=false where id='bind-clove-smoke-contest';
select is((select generation::integer from private.scenario_availability_fences where scenario_id='bind-clove-smoke-contest'),1,'withdrawal advances dependency fence');
update public.scenarios set is_published=true where id='bind-clove-smoke-contest';
set local role anon;
select throws_ok($$select public.get_library_playlist('7ecf3523-18cb-5cbe-a307-5b5cd43d1836')$$,'P0001','PLAYLIST_UNAVAILABLE','same-version restore does not resurrect old playlist');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"72000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.start_playlist_training_session('72000000-0000-4000-8000-000000000012','7ecf3523-18cb-5cbe-a307-5b5cd43d1836','72000000-0000-4000-8000-000000000099')->>'created','false','same active playlist resumes before availability or new publication checks');
insert into playlist_session_state select 'answered',public.submit_session_answer((value->'session'->>'id')::uuid,(value->'session'->'items'->0->>'id')::uuid,value->'session'->'items'->0->'challenge'->'options'->0->>'id','72000000-0000-4000-8000-000000000013',0) from playlist_session_state where name='start';
select is(value->'session'->>'phase','review','pinned session can answer after source withdrawal') from playlist_session_state where name='answered';
select is(public.get_active_training_session()->'playlist'->>'publicationVersion','2e061c34-3f9c-58cd-8923-926b353662fc','active summary retains frozen publication');
reset role;
select throws_ok($$update private.playlist_version_items set position=position where publication_id='2e061c34-3f9c-58cd-8923-926b353662fc'$$,'P0001','IMMUTABLE_RECORD','publication order cannot mutate');
select throws_ok($$update public.training_sessions set target_playlist_metadata='{}' where user_id='72000000-0000-4000-8000-000000000001'$$,'P0001','IMMUTABLE_RECORD','session playlist metadata cannot mutate');
select * from finish();
rollback;
